// Builds the storefront widget into the theme app extension assets folder.
// Never edit the output by hand: it is regenerated by this script.
import { build, context } from "esbuild";
import { fileURLToPath } from "node:url";
import path from "node:path";

const here = path.dirname(fileURLToPath(import.meta.url));
const outdir = path.resolve(here, "../../extensions/personalizer-theme/assets");
const watch = process.argv.includes("--watch");

const options = {
  entryPoints: { personalizer: path.join(here, "src/index.tsx") },
  outdir,
  bundle: true,
  format: "iife",
  target: ["es2020"],
  minify: true,
  sourcemap: false,
  jsx: "automatic",
  jsxImportSource: "preact",
  legalComments: "none",
  logLevel: "info",
};

if (watch) {
  const ctx = await context(options);
  await ctx.watch();
} else {
  await build(options);
}
